--liquibase formatted sql

--changeset agentic-dataops:001_baseline labels:baseline
--comment: Baseline of the app schema as it already exists on agentic-dataops-app (devices, sensor_readings, device_usage_charges). On that database this changeset is marked as run with `app-migrate baseline-sync` (changelog-sync --label-filter=baseline), NOT executed. On a fresh database `update` creates it.
CREATE TABLE "devices" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "serial" TEXT NOT NULL,
    "model" TEXT NOT NULL,
    "registered_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "devices_pkey" PRIMARY KEY ("id")
);

-- THE DEMO HAZARD: sensor_readings.id is int4 and approaching 2,147,483,647.
CREATE TABLE "sensor_readings" (
    "id" INT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "device_id" BIGINT NOT NULL,
    "metric" TEXT NOT NULL,
    "value" DECIMAL NOT NULL,
    "recorded_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "sensor_readings_pkey" PRIMARY KEY ("id")
);

-- Money is always NUMERIC(15,2).
CREATE TABLE "device_usage_charges" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "device_id" BIGINT NOT NULL,
    "amount" DECIMAL(15,2) NOT NULL,
    "charged_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "device_usage_charges_pkey" PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "devices_serial_key" ON "devices"("serial");
CREATE INDEX "sensor_readings_device_id_idx" ON "sensor_readings"("device_id");
CREATE INDEX "sensor_readings_recorded_at_idx" ON "sensor_readings"("recorded_at");

ALTER TABLE "sensor_readings" ADD CONSTRAINT "sensor_readings_device_id_fkey" FOREIGN KEY ("device_id") REFERENCES "devices"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "device_usage_charges" ADD CONSTRAINT "device_usage_charges_device_id_fkey" FOREIGN KEY ("device_id") REFERENCES "devices"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
-- Rollback is deliberately a NO-OP: the baseline describes pre-existing tables
-- holding app data, and rolling it back must never drop them. Roll back by tag
-- (every `update` tags the DB), which never reaches the baseline.
--rollback SELECT 'baseline rollback is intentionally a no-op' AS note;
